"""Inline script for the image-model dropdown (Settings -> Images and the avatar builder setup card): fills a <select> from /admin/image-models for the chosen provider, with a type-a-name fallback."""

JS = '<script>(function(){var p=document.querySelector("select[name=image_provider]"),w=document.getElementById("image-model-field");\nif(!p||!w)return;var sel=w.querySelector("select"),txt=w.querySelector("input[type=text]"),note=w.querySelector(".img-note");\nvar saved=txt.value;\nfunction fill(items,def){var cur=sel.value&&sel.value!="__other"?sel.value:saved;sel.innerHTML="";\nvar seen=false;items.forEach(function(m){var o=document.createElement("option");o.value=m.id;o.textContent=m.label+(m.id==def?" (default)":"");\nif(m.id==cur){o.selected=true;seen=true}sel.appendChild(o)});\nvar o=document.createElement("option");o.value="__other";o.textContent="other (type a name)...";sel.appendChild(o);\nif(!seen){if(cur&&cur!=def){sel.value="__other";txt.value=cur}else if(def&&items.some(function(m){return m.id==def})){sel.value=def}else{sel.value="__other"}}\nsync()}\nfunction sync(){if(sel.value=="__other"){txt.style.display="";txt.name="image_model";sel.name=""}else{txt.style.display="none";txt.name="";sel.name="image_model"}}\nfunction load(){note.textContent="loading models...";sel.disabled=true;\nfetch("/admin/image-models?provider="+encodeURIComponent(p.value),{credentials:"same-origin"}).then(function(r){return r.json()}).then(function(d){\nsel.disabled=false;fill(d.items||[],d.default||"");note.textContent=d.ok?(d.items.length+" image models available"):("couldn\'t load the list ("+(d.error||"error")+"): type a name instead")})\n.catch(function(){sel.disabled=false;sel.value="__other";sync();note.textContent="couldn\'t load the list: type a name instead"})}\nsel.addEventListener("change",sync);p.addEventListener("change",function(){saved="";txt.value="";load()});load()})();</script>'
